1	import { useEffect, useState, type FormEvent } from 'react';
2	import { ClientDetail } from './ClientDetail';
3	
4	// This arm's convention: the page component owns the feature's state, data loading and layout.
5	type Client = { id: number; name: string; email: string };
6	
7	// A client must carry a proper email address. Keep it simple and local to the feature: a single
8	// non-whitespace local part, an @, and a dotted domain.
9	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
10	
11	export function ClientsPage() {
12	  const [clients, setClients] = useState<Client[]>([]);
13	  const [search, setSearch] = useState('');
14	  const [name, setName] = useState('');
15	  const [email, setEmail] = useState('');
16	  const [emailError, setEmailError] = useState(false);
17	  const [openClientId, setOpenClientId] = useState<number | null>(null);
18	
19	  async function load() {
20	    const res = await fetch(`/api/clients?q=${encodeURIComponent(search)}`);
21	    if (res.ok) {
22	      setClients(await res.json());
23	    }
24	  }
25	
26	  // Reload whenever the search term changes — the server filters by name (case-insensitive).
27	  useEffect(() => {
28	    void load();
29	  }, [search]);
30	
31	  // Archiving tucks a client away: the row is kept but drops off the list and search. Close the
32	  // detail pane if it was open on the archived client, then reload the (now narrower) list.
33	  async function onArchive(id: number) {
34	    const res = await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
35	    if (res.ok) {
36	      if (openClientId === id) {
37	        setOpenClientId(null);
38	      }
39	      await load();
40	    }
41	  }
42	
43	  async function onSubmit(event: FormEvent) {
44	    event.preventDefault();
45	    if (!EMAIL_RE.test(email)) {
46	      setEmailError(true);
47	      return;
48	    }
49	    setEmailError(false);
50	    const res = await fetch('/api/clients', {
51	      method: 'POST',
52	      headers: { 'Content-Type': 'application/json' },
53	      body: JSON.stringify({ name, email }),
54	    });
55	    if (res.ok) {
56	      setName('');
57	      setEmail('');
58	      await load();
59	    }
60	  }
61	
62	  return (
63	    <section data-testid="clients-page">
64	      <h1>Clients</h1>
65	
66	      <input
67	        data-testid="client-search"
68	        placeholder="Search clients by name"
69	        value={search}
70	        onChange={(e) => setSearch(e.target.value)}
71	      />
72	
73	      <form data-testid="client-form" onSubmit={onSubmit}>
74	        <input
75	          data-testid="client-form-name"
76	          placeholder="Name"
77	          value={name}
78	          onChange={(e) => setName(e.target.value)}
79	        />
80	        <input
81	          data-testid="client-form-email"
82	          placeholder="Email"
83	          value={email}
84	          onChange={(e) => setEmail(e.target.value)}
85	        />
86	        {emailError && (
87	          <p data-testid="client-form-email-error">
88	            Enter a valid email address.
89	          </p>
90	        )}
91	        <button data-testid="client-form-submit" type="submit">
92	          Add client
93	        </button>
94	      </form>
95	
96	      {clients.length === 0 ? (
97	        <p data-testid="clients-empty">No clients yet.</p>
98	      ) : (
99	        <table data-testid="clients-table">
100	          <thead>
101	            <tr>
102	              <th>Name</th>
103	              <th>Email</th>
104	              <th></th>
105	            </tr>
106	          </thead>
107	          <tbody>
108	            {clients.map((client) => (
109	              <tr key={client.id} data-testid={`client-row-${client.id}`}>
110	                <td data-testid="client-name">{client.name}</td>
111	                <td data-testid="client-email">{client.email}</td>
112	                <td>
113	                  <button
114	                    data-testid={`client-open-${client.id}`}
115	                    type="button"
116	                    onClick={() => setOpenClientId(client.id)}
117	                  >
118	                    Open
119	                  </button>
120	                  <button
121	                    data-testid={`client-archive-${client.id}`}
122	                    type="button"
123	                    onClick={() => void onArchive(client.id)}
124	                  >
125	                    Archive
126	                  </button>
127	                </td>
128	              </tr>
129	            ))}
130	          </tbody>
131	        </table>
132	      )}
133	
